sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    var riskId = api.data.glide_form_item.nowActivityStreamComposeConnected.sysId;
    if (riskId != -1) {
        api.data.create_assessment_from_scope_1.execute({
            "riskSysId": riskId,
            "scopeId": api.data.look_up_record_1.result.sys_id.value
        });
        helpers.modal.close();
        api.emit("REFRESH_LIST",{});
        api.emit("RECORD#RELATED_LIST_REFRESH_REQUESTED",{
            relatedListName: "REL:8afaa2f5b79600102a279e98ee11a9bb"
        });
    }
}
